56	static libzippp_uint16 convertCompressionToLibzip(CompressionMethod comp) {
57	    switch(comp) {
58	        case CompressionMethod::STORE:
59	            return ZIP_CM_STORE;
60	#ifdef ZIP_CM_BZIP2
61	        case CompressionMethod::BZIP2:
62	            return ZIP_CM_BZIP2;
63	#endif
64	        case CompressionMethod::DEFLATE:
65	            return ZIP_CM_DEFLATE;
66	#ifdef ZIP_CM_XZ
67	        case CompressionMethod::XZ:
68	            return ZIP_CM_XZ;
69	#endif
70	#ifdef ZIP_CM_ZSTD
71	        case CompressionMethod::ZSTD:
72	            return ZIP_CM_ZSTD;
73	#endif
74	        default:
75	            return ZIP_CM_DEFAULT;
76	    }
77	}
