103	    static void callErrorHandlingCallbackFunc(const std::string& message, int zip_error_code, int system_error_code, ErrorHandlerCallback* callback) {
104	        zip_error_t error;
105	        zip_error_init(&error);
106	        zip_error_set(&error, zip_error_code, system_error_code);
107	        std::string strerror(zip_error_strerror(&error));
108	        (*callback)(message, strerror, zip_error_code, system_error_code);
109	        zip_error_fini(&error);
110	    }
111	
112	    static void callErrorHandlingCallback(zip* zipHandle, const std::string& msg, ErrorHandlerCallback* callback) {
113	        if (zipHandle!=nullptr) {
114	            zip_error_t* error_code = zip_get_error(zipHandle);
115	            callErrorHandlingCallbackFunc(msg, error_code->zip_err, error_code->sys_err, callback);
116	        } else {
117	            callErrorHandlingCallbackFunc("", -1, -1, callback);
118	        }
119	    }
120	
121	    static void callErrorHandlingCallback(zip_error_t* error, const std::string& msg, ErrorHandlerCallback* callback) {
122	        int error_code_zip, error_code_system;
123	        error_code_zip = zip_error_code_zip(error);
124	        error_code_system = zip_error_code_system(error);
125	        callErrorHandlingCallbackFunc(msg, error_code_zip, error_code_system, callback);
126	    }
127	}
