517	string ZipArchive::getComment(State state) const {
518	    if (!isOpen()) { return string(); }
519	
520	    int flag = 0;
521	    if (state==Original) { flag = flag | LIBZIPPP_ORIGINAL_STATE_FLAGS; }
522	    else { flag = flag | ZIP_FL_ENC_GUESS; }
523	
524	    int length = 0;
525	    const char* comment = zip_get_archive_comment(zipHandle, &length, flag);
526	    if (comment==nullptr) { return string(); }
527	    return string(comment, length);
528	}
