561	ZipEntry ZipArchive::createEntry(struct zip_stat* stat) const {
562	    string name(stat->name);
563	    libzippp_uint64 index = stat->index;
564	    libzippp_uint64 size = stat->size;
565	    libzippp_uint16 compMethod;
566	    if (useArchiveCompressionMethod) {
567	        compMethod = this->compressionMethod;
568	    } else {
569	        compMethod = stat->comp_method;
570	    }
571	    libzippp_uint16 encMethod = stat->encryption_method;
572	    libzippp_uint64 sizeComp = stat->comp_size;
573	    int crc = stat->crc;
574	    time_t time = stat->mtime;
575	
576	    return ZipEntry(this, name, index, time, compMethod, compressionLevel, encMethod, size, sizeComp, crc);
577	}
