658	ZipEntry ZipArchive::getEntry(libzippp_int64 index, State state) const {
659	    if (isOpen()) {
660	        struct zip_stat stat;
661	        zip_stat_init(&stat);
662	        int flag = state==Original ? LIBZIPPP_ORIGINAL_STATE_FLAGS : ZIP_FL_ENC_GUESS;
663	        int result = zip_stat_index(zipHandle, index, flag, &stat);
664	        if (result==0) {
665	            return createEntry(&stat);
666	        } else {
667	            //index not found / invalid index
668	        }
669	    }
670	    return ZipEntry();
671	}
