746	int ZipArchive::deleteEntry(const ZipEntry& entry) const {
747	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
748	    if (entry.zipFile!=this) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
749	    if (mode==ReadOnly) { return LIBZIPPP_ERROR_NOT_ALLOWED; } //deletion not allowed
750	
751	    if (entry.isFile()) {
752	        int result = zip_delete(zipHandle, entry.getIndex());
753	        if (result==0) { return 1; }
754	        return LIBZIPPP_ERROR_UNKNOWN; //unable to delete the entry
755	    } else {
756	        int counter = 0;
757	        vector<ZipEntry> allEntries = getEntries();
758	        vector<ZipEntry>::const_iterator eit;
759	        for(eit=allEntries.begin() ; eit!=allEntries.end() ; ++eit) {
760	            ZipEntry ze = *eit;
761	            string::size_type startPosition = ze.getName().find(entry.getName());
762	            if (startPosition==0) {
763	                int result = zip_delete(zipHandle, ze.getIndex());
764	                if (result==0) { ++counter; }
765	                else { return LIBZIPPP_ERROR_UNKNOWN; } //unable to remove the current entry
766	            }
767	        }
768	        return counter;
769	    }
770	}
