772	int ZipArchive::deleteEntry(const string& e) const {
773	    ZipEntry entry = getEntry(e);
774	    if (entry.isNull()) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
775	    return deleteEntry(entry);
776	}
777	
778	int ZipArchive::renameEntry(const ZipEntry& entry, const string& newNameIn) const {
779	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
780	    if (entry.isNull() || entry.zipFile!=this) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
781	    if (mode==ReadOnly) { return LIBZIPPP_ERROR_NOT_ALLOWED; } //renaming not allowed
782	    if (newNameIn.length()==0) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
783	
784	    bool isDir = entry.isDirectory();
785	    string newName = newNameIn;
786	    if (isDir) {
787	        //a '/' is automatically appended to the destination of a directory
788	        if (!LIBZIPPP_ENTRY_IS_DIRECTORY(newName)) { newName += LIBZIPPP_ENTRY_PATH_SEPARATOR; }
789	    } else {
790	        if (LIBZIPPP_ENTRY_IS_DIRECTORY(newName)) { return LIBZIPPP_ERROR_INVALID_PARAMETER; } //a file cannot be renamed as a directory
791	    }
792	
793	    string sourceName = entry.getName();
794	    if (newName==sourceName) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
795	
796	    /*
797	     * Enumerate ALL the entries of the CURRENT state of the archive (i.e. including any
798	     * uncommitted addition/deletion/replacement/rename). Slots freed by zip_delete are
799	     * reported with a null name by libzip and simply skipped.
800	     */
801	    struct RenameItem {
802	        zip_uint64_t index;
803	        string oldName;
804	        string targetName;
805	    };
806	    vector<RenameItem> movedItems;
807	    vector<string> externalNames;
808	
809	    zip_int64_t nbSlots = zip_get_num_entries(zipHandle, 0);
810	    for(zip_int64_t i=0 ; i<nbSlots ; ++i) {
811	        const char* currentName = zip_get_name(zipHandle, (zip_uint64_t)i, ZIP_FL_ENC_GUESS);
812	        if (currentName==nullptr) { continue; } //entry deleted in the current (uncommitted) state
813	
814	        string name(currentName);
815	        bool participates = false;
816	        string targetName;
817	        if (isDir) {
818	            if (name==sourceName) {
819	                participates = true;
820	                targetName = newName;
821	            } else if (name.compare(0, sourceName.length(), sourceName)==0) {
822	                participates = true; //descendant of the moved directory
823	                targetName = newName + name.substr(sourceName.length());
824	            }
825	        } else {
826	            participates = (name==sourceName);
827	            targetName = newName;
828	        }
829	
830	        if (participates) {
831	            movedItems.push_back(RenameItem{(zip_uint64_t)i, name, targetName});
832	        } else {
833	            externalNames.push_back(name);
834	        }
835	    }
836	
837	    //the source entry itself must be part of the current archive
838	    bool sourceFound = false;
839	    for(vector<RenameItem>::const_iterator it=movedItems.begin() ; it!=movedItems.end() ; ++it) {
840	        if (it->oldName==sourceName) { sourceFound = true; break; }
841	    }
842	    if (!sourceFound) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
843	
844	    /*
845	     * Detect conflicts against the CURRENT state only: any entry that does not participate
846	     * in the move must not occupy the destination itself nor lie below it. Entries whose
847	     * parent directories are only implicit (no explicit directory entry in the archive) are
848	     * listed here as well, so a file such as new/target/last.txt prevents src/ from being
849	     * moved to new/target/ even when no new/ or new/target/ directory entry exists.
850	     */
851	    for(vector<string>::const_iterator it=externalNames.begin() ; it!=externalNames.end() ; ++it) {
852	        const string& external = *it;
853	        if (isDir) {
854	            if (external==newName || external.compare(0, newName.length(), newName)==0) {
855	                return LIBZIPPP_ERROR_UNKNOWN; //destination already occupied by an external entry: no overwrite, no merge
856	            }
857	        } else {
858	            if (external==newName) {
859	                return LIBZIPPP_ERROR_UNKNOWN; //the destination file already exists
860	            }
861	        }
862	    }
863	
864	    /*
865	     * Compute the (explicit) parent directories that will be missing once the entries have
866	     * been moved. A directory that is itself moved never has to be re-created here (it keeps
867	     * existing as an entry, only its name changes), even when a moved entry's new parent
868	     * chain goes through it.
869	     */
870	    vector<string> parentsToCreate;
871	    for(vector<RenameItem>::const_iterator it=movedItems.begin() ; it!=movedItems.end() ; ++it) {
872	        //for a directory target (ending with '/'), the first parent to consider is above the
873	        //target directory itself, hence the search starts at the penultimate separator
874	        string::size_type searchPos = it->targetName.length()-1;
875	        if (LIBZIPPP_ENTRY_IS_DIRECTORY(it->targetName) && searchPos>0) { searchPos -= 1; }
876	        string::size_type slash = it->targetName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR, searchPos);
877	        while(slash!=string::npos && slash>0) {
878	            string parent = it->targetName.substr(0, slash+1);
879	
880	            //a moved destination already exists as an entry after the move
881	            bool isMovedDestination = false;
882	            for(vector<RenameItem>::const_iterator mit=movedItems.begin() ; mit!=movedItems.end() ; ++mit) {
883	                if (mit->targetName==parent) { isMovedDestination = true; break; }
884	            }
885	            if (isMovedDestination) { break; } //all the ancestors above are shared with this moved directory
886	
887	            //an external entry already provides the directory (explicitly)
888	            bool isExternal = false;
889	            for(vector<string>::const_iterator eit=externalNames.begin() ; eit!=externalNames.end() ; ++eit) {
890	                if (*eit==parent) { isExternal = true; break; }
891	            }
892	            if (isExternal) { break; } //the prefix chain up to this directory already exists
893	
894	            bool alreadyScheduled = false;
895	            for(vector<string>::const_iterator pit=parentsToCreate.begin() ; pit!=parentsToCreate.end() ; ++pit) {
896	                if (*pit==parent) { alreadyScheduled = true; break; }
897	            }
898	            if (!alreadyScheduled) { parentsToCreate.push_back(parent); }
899	            slash = it->targetName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR, slash-1);
900	        }
901	    }
902	    //create the parents from the shallowest to the deepest
903	    std::sort(parentsToCreate.begin(), parentsToCreate.end());
904	
905	    /*
906	     * Apply the rename deepest-first. This ordering is what makes moving a directory below
907	     * its own path possible (e.g. a/ to a/b/): the descendants free the names the ancestors
908	     * are renamed to, and the freshly re-created parent directories are not touched.
909	     */
910	    std::sort(movedItems.begin(), movedItems.end(),
911	              [](const RenameItem& a, const RenameItem& b) { return a.targetName > b.targetName; });
912	
913	    vector<zip_uint64_t> renamedIndices;
914	    vector<string> renamedOldNames;
915	    bool failure = false;
916	    for(vector<RenameItem>::const_iterator it=movedItems.begin() ; it!=movedItems.end() ; ++it) {
917	        int result = zip_file_rename(zipHandle, it->index, it->targetName.c_str(), ZIP_FL_ENC_GUESS);
918	        if (result!=0) { failure = true; break; }
919	        renamedIndices.push_back(it->index);
920	        renamedOldNames.push_back(it->oldName);
921	    }
922	
923	    //create the missing parent directories (e.g. re-create a/ when a/ moved to a/b/)
924	    vector<zip_uint64_t> createdDirIndices;
925	    if (!failure) {
926	        for(vector<string>::const_iterator it=parentsToCreate.begin() ; it!=parentsToCreate.end() ; ++it) {
927	            zip_int64_t dirIndex = zip_dir_add(zipHandle, it->c_str(), ZIP_FL_ENC_GUESS);
928	            if (dirIndex<0) { failure = true; break; }
929	            createdDirIndices.push_back((zip_uint64_t)dirIndex);
930	        }
931	    }
932	
933	    if (failure) {
934	        /*
935	         * The move could not be completed: undo everything done during THIS call so that the
936	         * archive is restored to its exact pre-call state. The directories created during
937	         * the move are removed first (they may occupy the original names), then the renames
938	         * are replayed in the reverse order (shallowest-first). Any other pending change is
939	         * left untouched.
940	         */
941	        for(vector<zip_uint64_t>::reverse_iterator dit=createdDirIndices.rbegin() ; dit!=createdDirIndices.rend() ; ++dit) {
942	            zip_delete(zipHandle, *dit);
943	        }
944	        for(zip_int64_t k=(zip_int64_t)renamedIndices.size()-1 ; k>=0 ; --k) {
945	            zip_file_rename(zipHandle, renamedIndices[(size_t)k], renamedOldNames[(size_t)k].c_str(), ZIP_FL_ENC_GUESS);
946	        }
947	        return LIBZIPPP_ERROR_UNKNOWN;
948	    }
949	
950	    return (int)movedItems.size();
951	}
