1009	    if (lastSlash!=string::npos) { //creates the needed parent directories
1010	        string dirEntry = entryName.substr(0, lastSlash+1);
1011	        bool dadded = addEntry(dirEntry);
1012	        if (!dadded) { return false; }
1013	    }
1014	
1015	    zip_source* source = zip_source_buffer(zipHandle, data, length, freeData);
1016	    if (source!=nullptr) {
1017	        libzippp_int64 result = zip_file_add(zipHandle, entryName.c_str(), source, ZIP_FL_OVERWRITE);
1018	        if (result>=0) {
1019	            zip_file_set_mtime(zipHandle, result, time(nullptr), 0);
1020	            if (useArchiveCompressionMethod) {
