1022	            }
1023	#ifdef LIBZIPPP_WITH_ENCRYPTION
1024	            if (isEncrypted()) {
1025	                if (zip_file_set_encryption(zipHandle,result,encryptionMethod,nullptr)!=0) { //unable to encrypt
1026	                    zip_source_free(source);
1027	                } else {
1028	                    return true;
1029	                }
1030	            } else {
1031	                return true;
1032	            }
1033	#else
1034	            return true;
1035	#endif
1036	        } else {
1037	            //unable to add the file
1038	            zip_source_free(source);
1039	        }
1040	    } else {
1041	        //unable to create the zip_source
1042	    }
1043	    return false;
