1050	bool ZipArchive::addEntry(const string& entryName) const {
1051	    if (!isOpen()) { return false; }
1052	    if (mode==ReadOnly) { return false; } //adding not allowed
1053	    if (!LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
1054	
1055	    string::size_type nextSlash = entryName.find(LIBZIPPP_ENTRY_PATH_SEPARATOR);
1056	    while (nextSlash!=string::npos) {
1057	        string pathToCreate = entryName.substr(0, nextSlash+1);
1058	        if (!hasEntry(pathToCreate)) {
1059	            libzippp_int64 result = zip_dir_add(zipHandle, pathToCreate.c_str(), ZIP_FL_ENC_GUESS);
1060	            if (result==-1) { return false; }
1061	        }
1062	        nextSlash = entryName.find(LIBZIPPP_ENTRY_PATH_SEPARATOR, nextSlash+1);
1063	    }
1064	
1065	    return true;
1066	}
