1094	int ZipArchive::readEntry(const ZipEntry& zipEntry, std::function<bool(const void*,libzippp_uint64)> writeFunc, State state, libzippp_uint64 chunksize) const {
1095	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
1096	    if (zipEntry.zipFile!=this) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
1097	
1098	    //resolve the entry in the requested state: its existence and uncompressed size depend
1099	    //on the state. When it does not exist in the state, no data is delivered at all.
1100	    libzippp_uint64 maxSize = 0;
1101	    ZipEntry resolved = resolveEntry(zipEntry, state, &maxSize);
1102	    if (resolved.isNull()) { return LIBZIPPP_ERROR_FOPEN_FAILURE; }
1103	
1104	    if (!chunksize) { chunksize = LIBZIPPP_DEFAULT_CHUNK_SIZE; } // use the default chunk size (512K) if not specified by the user
1105	
1106	    int flag = stateFlags(state);
1107	    struct zip_file* zipFile = zip_fopen_index(zipHandle, resolved.getIndex(), flag);
1108	    if (!zipFile) { return LIBZIPPP_ERROR_FOPEN_FAILURE; }
1109	
1110	    int iRes = LIBZIPPP_OK;
1111	
1112	    //an empty content succeeds without reading anything; a single zero-length delivery is
1113	    //still signalled to the output (this matches the historical behavior)
1114	    if (maxSize==0) {
1115	        if (!writeFunc("", 0)) {
1116	            zip_fclose(zipFile);
1117	            return LIBZIPPP_ERROR_OWRITE_FAILURE;
1118	        }
1119	        zip_fclose(zipFile);
1120	        return LIBZIPPP_OK;
1121	    }
1122	
1123	    //only allocate what a single delivery may need (the whole content when it is smaller
1124	    //than the chunk size) instead of the chunk size in every case
1125	    libzippp_uint64 bufferSize = maxSize<chunksize ? maxSize : chunksize;
1126	    char* data = NEW_CHAR_ARRAY(bufferSize)
1127	    if (data!=nullptr) {
1128	        //stream the exact, state-resolved length in successive chunks: this delivers the
1129	        //whole content exactly once (chunksize bigger than, equal to, or not a divisor of
1130	        //the content length are all handled by the same loop)
1131	        libzippp_uint64 remaining = maxSize;
1132	        while (remaining>0) {
1133	            libzippp_uint64 toRead = remaining<bufferSize ? remaining : bufferSize;
1134	            libzippp_int64 result = zip_fread(zipFile, data, toRead);
1135	            if (result<0) {
1136	                iRes = LIBZIPPP_ERROR_FREAD_FAILURE;
1137	                break;
1138	            }
1139	            if (static_cast<libzippp_uint64>(result)!=toRead) {
1140	                iRes = LIBZIPPP_ERROR_OWRITE_INDEX_FAILURE;
1141	                break;
1142	            }
1143	            if (!writeFunc(data, toRead)) {
1144	                iRes = LIBZIPPP_ERROR_OWRITE_FAILURE;
1145	                break;
1146	            }
1147	            remaining -= toRead;
1148	        }
1149	        delete[] data;
1150	    } else {
1151	        iRes = LIBZIPPP_ERROR_MEMORY_ALLOCATION;
1152	    }
1153	    zip_fclose(zipFile);
1154	    return iRes;
1155	}
