    /* ---------- 2. File archive: expiry on close/discard/destroy ---------- */
    const char* payload = "hello-entry-lifecycle";
    {
        ZipArchive z("life.zip");
        assert(z.open(ZipArchive::New));
        z.addData("dir/file.txt", payload, strlen(payload));
        assert(z.close()==LIBZIPPP_OK);
    }
    ZipEntry copy;
    {
        ZipArchive z("life.zip");
        assert(z.open(ZipArchive::ReadOnly));
        ZipEntry e = z.getEntry("dir/file.txt");
        assert(!e.isNull());
        assert(e.getSize()==strlen(payload));
        copy = e;                 // copy outlives archive block
        ZipEntry copy2 = e;

        // usable during the opening
        assert(copy.readAsText()==payload);
        assert(!copy.readAsBinaryString().empty());
        {
            stringstream ss;
            assert(copy.readContent(ss)==LIBZIPPP_OK);
            assert(ss.str()==payload);
        }

        // repeated open with same mode does not invalidate
        assert(z.open(ZipArchive::ReadOnly));
        assert(e.readAsText()==payload);

        assert(z.close()==LIBZIPPP_OK);

        // now expired: reads empty / nullptr, metadata retained, isNull unchanged
        assert(!e.isNull());
        assert(e.getName()=="dir/file.txt");
        assert(e.getSize()==strlen(payload));
        assert(e.readAsText()=="");
        assert(e.readAsBinaryString().empty());
        assert(e.readAsBinary()==nullptr);
        assert(e.getComment()=="");
        assert(!e.setComment("c"));
        assert(!e.setCompressionMethod(STORE));
        assert(!e.setCompressionLevel(1));
        {
            stringstream ss;
            assert(e.readContent(ss)==LIBZIPPP_ERROR_NOT_OPEN);
            assert(copy2.readContent(ss)==LIBZIPPP_ERROR_NOT_OPEN);
            assert(ss.str().empty());
        }
        // archive closed: NOT_OPEN via archive entries
        {
            stringstream ss;
            assert(z.readEntry(e, ss)==LIBZIPPP_ERROR_NOT_OPEN);
            assert(z.deleteEntry(e)==LIBZIPPP_ERROR_NOT_OPEN);
            assert(z.renameEntry(e,"x")==LIBZIPPP_ERROR_NOT_OPEN);
            assert(z.readEntry(e)==nullptr);
            assert(z.getEntryComment(e)=="");
            assert(!z.setEntryComment(e,"c"));
            assert(!z.setEntryCompressionConfig(const_cast<ZipEntry&>(e)));
        }
    }
    // archive object destroyed, copy outlives it: no crash, no dangling deref
    assert(!copy.isNull());
    assert(copy.getName()=="dir/file.txt");
    assert(copy.readAsText()=="");
    assert(copy.readAsBinary()==nullptr);
    {
        stringstream ss;
        assert(copy.readContent(ss)==LIBZIPPP_ERROR_NOT_OPEN);
        assert(ss.str().empty());
    }

    /* ---------- 3. Reopen same path, same name/index: old stays dead, new works ---------- */
    {
        ZipArchive z("life.zip");
        assert(z.open(ZipArchive::ReadOnly));
        ZipEntry fresh = z.getEntry("dir/file.txt");
        assert(!fresh.isNull());
        assert(fresh.getIndex()==copy.getIndex()); // same index
        assert(fresh.getName()==copy.getName());   // same name
        // old copy cannot operate on this opening
        {
            stringstream ss;
            assert(z.readEntry(copy, ss)==LIBZIPPP_ERROR_INVALID_ENTRY);
            assert(ss.str().empty());
            g_calls = 0; g_received.clear();
            int r = z.readEntry(copy, [](const void* d, uint64_t n){ ++g_calls; g_received.append((const char*)d,(size_t)n); return true; });
            assert(r==LIBZIPPP_ERROR_INVALID_ENTRY);
            assert(g_calls==0 && g_received.empty()); // callback never invoked
        }
        assert(z.deleteEntry(copy)==LIBZIPPP_ERROR_INVALID_ENTRY);
        assert(z.renameEntry(copy,"z")==LIBZIPPP_ERROR_INVALID_ENTRY);
        assert(z.readEntry(copy)==nullptr);
        assert(z.getEntryComment(copy)=="");
        assert(!z.setEntryComment(copy,"c"));
        assert(!z.setEntryCompressionConfig(const_cast<ZipEntry&>(copy)));
        // freshly queried entry works
        assert(fresh.readAsText()==payload);
        {
            stringstream ss;
            assert(z.readEntry(fresh, ss)==LIBZIPPP_OK);
            assert(ss.str()==payload);
        }
        // lookup-failure null entry behaves like null
        ZipEntry none = z.getEntry("missing");
        assert(none.isNull());
        assert(none.readAsText()=="");
        assert(z.readEntry(none)==nullptr);
        {
            stringstream ss;
            assert(z.readEntry(none, ss)==LIBZIPPP_ERROR_INVALID_ENTRY);
            assert(ss.str().empty());
        }
        assert(z.deleteEntry(none)==LIBZIPPP_ERROR_INVALID_ENTRY);
        assert(z.renameEntry(none,"q")==LIBZIPPP_ERROR_INVALID_ENTRY);
        assert(z.close()==LIBZIPPP_OK);
    }

    /* ---------- 4. Foreign archive entry ---------- */
    {
        ZipArchive a("life.zip");
        ZipArchive b("life2.zip");
        b.open(ZipArchive::New);
        b.addData("dir/file.txt", payload, strlen(payload));
        assert(b.close()==LIBZIPPP_OK);
        assert(a.open(ZipArchive::ReadOnly));
        assert(b.open(ZipArchive::ReadOnly));
        ZipEntry ea = a.getEntry("dir/file.txt");
        ZipEntry eb = b.getEntry("dir/file.txt");
        assert(ea.getIndex()==eb.getIndex());
        assert(a.readEntry(eb)==nullptr);
        {
            stringstream ss;
            assert(a.readEntry(eb, ss)==LIBZIPPP_ERROR_INVALID_ENTRY);
            assert(ss.str().empty());
        }
        assert(a.deleteEntry(eb)==LIBZIPPP_ERROR_INVALID_ENTRY);
        assert(a.renameEntry(eb,"x")==LIBZIPPP_ERROR_INVALID_ENTRY);
        assert(a.getEntryComment(eb)=="");
        assert(!a.setEntryComment(eb,"x"));
        assert(!a.setEntryCompressionConfig(const_cast<ZipEntry&>(eb)));
        assert(ea.readAsText()==payload);
        a.close(); b.close(); b.unlink();
    }

    /* ---------- 5. discard invalidates; copies don't block discard ---------- */
    {
        ZipArchive z("life.zip");
        assert(z.open(ZipArchive::Write));
        ZipEntry e = z.getEntry("dir/file.txt");
        ZipEntry c = e;
        z.setEntryComment(e,"keepme");
        z.discard(); // changes rolled back, no hang
        assert(!z.isOpen());
        assert(e.readAsText()=="");
        assert(c.readAsBinary()==nullptr);
        {
            stringstream ss;
            assert(c.readContent(ss)==LIBZIPPP_ERROR_NOT_OPEN);
        }
    }

    /* ---------- 6. ZipArchive::free invalidates ---------- */
    {
        ZipArchive* z = new ZipArchive("life.zip");
        assert(z->open(ZipArchive::ReadOnly));
        ZipEntry e = z->getEntry("dir/file.txt");
        ZipArchive::free(z);
        assert(!e.isNull());
        assert(e.readAsText()=="");
        assert(e.readAsBinary()==nullptr);
        assert(!e.setComment("nope"));
        {
            stringstream ss;
            assert(e.readContent(ss)==LIBZIPPP_ERROR_NOT_OPEN);
        }
    }

    /* ---------- 7. fromBuffer / fromWritableBuffer same rules ---------- */
    {
        // build an in-memory zip first
        void* buf = nullptr;
        uint32_t len = 0;
        {
            ZipArchive z("");
            // use writable buffer created empty (New)
        }
        size_t srcsize = 0;
        void* src = nullptr;
        {
            ZipArchive* z = ZipArchive::fromWritableBuffer(&src, 0, ZipArchive::New);
            assert(z);
            assert(z->addData("b.bin", payload, strlen(payload)));
            assert(z->close()==LIBZIPPP_OK);
            srcsize = (size_t)z->getBufferLength();
            ZipArchive::free(z);
        }
        assert(src && srcsize>0);
        ZipEntry kept;
        {
            ZipArchive* z = ZipArchive::fromBuffer(src, (uint32_t)srcsize);
            assert(z);
            ZipEntry e = z->getEntry("b.bin");
            assert(e.readAsText()==payload);
            kept = e;
            ZipArchive::free(z); // archive gone, source stays valid
        }
        assert(!kept.isNull());
        assert(kept.readAsText()=="");
        assert(kept.readAsBinary()==nullptr);
        {
            stringstream ss;
            assert(kept.readContent(ss)==LIBZIPPP_ERROR_NOT_OPEN);
            assert(ss.str().empty());
        }

        // writable buffer close commits and invalidates
        ZipEntry wkept;
        {
            ZipArchive* z = ZipArchive::fromWritableBuffer(&src, (uint32_t)srcsize, ZipArchive::Write);
            assert(z);
            wkept = z->getEntry("b.bin");
            assert(z->addData("more","ZZZ",3));
            assert(z->close()==LIBZIPPP_OK); // committed into buffer
            assert(z->getBufferLength()>0);
            assert(wkept.readAsText()=="");
            ZipArchive::free(z);
        }
        assert(wkept.readAsBinary()==nullptr);
        free(src);
    }

    /* ---------- 8. Cancelled close: stays open, entries survive, retry commit/discard ---------- */
    {
        ZipArchive z("life.zip");
        assert(z.open(ZipArchive::Write));
        z.addData("cancel-check.txt", payload, strlen(payload));
        ZipEntry e = z.getEntry("cancel-check.txt");
        CancelAlways cancel;
        z.addProgressListener(&cancel);
        int rc = z.close();
        if (rc!=LIBZIPPP_OK) {
            // libzip honoured the cancellation: archive still open and usable
            assert(z.isOpen());
            assert(!e.isNull());
            assert(e.readAsText()==payload);
            assert(z.setEntryComment(e,"still-here"));
            {
                stringstream ss;
                assert(e.readContent(ss)==LIBZIPPP_OK);
                assert(ss.str()==payload);
            }
            // retry without the cancelling listener
            z.removeProgressListener(&cancel);
            assert(z.close()==LIBZIPPP_OK);
            // now expired
            assert(e.readAsText()=="");
            {
                stringstream ss;
                assert(e.readContent(ss)==LIBZIPPP_ERROR_NOT_OPEN);
            }
        } else {
            // libzip finished before polling cancel on a tiny archive: still, close really ended
            assert(!z.isOpen());
            assert(e.readAsText()=="");
        }
    }

    /* ---------- 9. discarded after cancelled close ---------- */
    {
        ZipArchive z("life.zip");
        assert(z.open(ZipArchive::Write));
        z.addData("x.txt", payload, strlen(payload));
        ZipEntry e = z.getEntry("x.txt");
        CancelAlways cancel;
        z.addProgressListener(&cancel);
        if (z.close()!=LIBZIPPP_OK) {
            assert(z.isOpen());
            assert(e.readAsText()==payload);
            z.removeProgressListener(&cancel);
            z.discard();
            assert(!z.isOpen());
            assert(e.readAsText()=="");
            assert(e.readAsBinary()==nullptr);
        } else {
            assert(!z.isOpen());
        }
    }

    /* ---------- 10. Copies do not impede commit ---------- */
    {
        remove("life.zip");
        ZipArchive z("life.zip");
        assert(z.open(ZipArchive::New));
        z.addData("a","1",1);
        ZipEntry e = z.getEntry("a");
        ZipEntry c = e;
        assert(z.close()==LIBZIPPP_OK);
        // changes were committed
        ZipArchive r("life.zip");
        assert(r.open(ZipArchive::ReadOnly));
        assert(r.hasEntry("a"));
        assert(r.getEntry("a").readAsText()=="1");
        // old copies still unusable against the reopened archive
        assert(r.readEntry(c)==nullptr);
        r.close(); r.unlink();
    }

    cout << "ALL SCRATCH CHECKS PASSED" << endl;
    (void)streamTouched("");
    return 0;
}

